 motion=json.loads((O/r['motion']).read_text());attack=[f for f in motion['frames'] if r['strike_start']<=f['t']<=r['strike_end']];assert attack;both=sum(len({p['role'] for p in f['people']})==2 for f in attack)/len(attack);print(r['id'],r['source_id'],'strike frames',len(attack),'both tracks',round(both,2));assert both>=.5
